const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
async function get(u){const r=await fetch(u,{cache:'no-store'});if(!r.ok)throw Error();return r.json()}
function ordinal(v){return v==1?'st':v==2?'nd':v==3?'rd':'th'}
function historic(records){if(!records.length)return '';const overall=records.filter(x=>/overall league/i.test(x.event_name||'')),events=records.filter(x=>!/overall league/i.test(x.event_name||''));const standing=x=>'<article class="league-standing"><span>'+esc(x.season)+' · '+esc(x.division)+'</span><strong>'+esc(x.position)+'<sup>'+ordinal(x.position)+'</sup></strong><b>Overall league standing</b></article>';const table=items=>'<div class="table-scroll"><table><thead><tr><th>Event</th><th>Place</th></tr></thead><tbody>'+items.map(x=>'<tr><td>'+esc(x.event_name)+'</td><td><strong>'+esc(x.position)+'</strong></td></tr>').join('')+'</tbody></table></div>';const blocks=overall.map(x=>{const related=events.filter(e=>e.season===x.season&&e.division===x.division);return related.length?'<details class="league-season"><summary>'+standing(x)+'<em>View '+related.length+' events</em></summary>'+table(related)+'</details>':standing(x)}).join('');return '<section class="history-card historical-card"><div class="history-heading"><span>European Onewheel League</span><h2>Historic league record</h2><p>Select a league standing to see its individual event placings.</p></div><div class="league-standing-grid">'+blocks+'</div></section>'}
function historySearch(){return '<section class="history-search" id="historic-search"><span>European Onewheel League</span><h2>Find historic results</h2><p>No historic record was matched to this rider. Search an earlier name to view their league history.</p><form><input id="historic-name" type="search" minlength="2" placeholder="Search historic rider name" autocomplete="off"><button class="btn" type="submit">Search</button></form><div id="historic-search-results"></div></section>'}
async function post(u,body){const r=await fetch(u,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d}
function wireHistorySearch(athleteId){const form=$('#historic-search form');if(!form)return;const input=$('#historic-name'),output=$('#historic-search-results');form.onsubmit=async e=>{e.preventDefault();const q=input.value.trim();if(q.length<2){output.textContent='Enter at least two letters.';return}output.textContent='Searching…';try{const matches=await get('/api/public/historical/search?name='+encodeURIComponent(q));if(!matches.length){output.textContent='No historic names found.';return}output.innerHTML='<div class="historic-match-list">'+matches.map(x=>'<button type="button" data-key="'+encodeURIComponent(x.normal_name)+'"><strong>'+esc(x.rider_name)+'</strong><span>'+x.records+' records</span></button>').join('')+'</div>';output.querySelectorAll('button').forEach(b=>b.onclick=async()=>{output.textContent='Loading history…';const records=await get('/api/public/historical/by-name?key='+b.dataset.key);output.innerHTML='<div class="historic-search-history"><button class="btn request-history-match" data-key="'+b.dataset.key+'">Request permanent match</button>'+historic(records)+'</div>';output.querySelector('.request-history-match').onclick=async e=>{const button=e.currentTarget;button.disabled=true;try{await post('/api/public/historical/match-request',{athleteId,key:decodeURIComponent(button.dataset.key)});button.textContent='Submitted for admin approval'}catch(err){button.disabled=false;button.textContent=err.message}}})}catch{output.textContent='Historic search is temporarily unavailable.'}}}
async function render(){const id=new URLSearchParams(location.search).get('id');if(!id){$('#rider-content').innerHTML='<p class="empty">Choose a rider from the live results to view their complete record.</p>';return}try{const rider=await get('/api/public/riders/'+encodeURIComponent(id)),records=rider.records||[],historical=rider.historical||[],first=records[0]||{},fastest=records.reduce((best,x)=>!best||x.time<best.time?x:best,null);document.title=`${rider.name} · OWAR 2026`;$('#back-results').href=first.tournament?'/?event='+encodeURIComponent(first.tournament.toLowerCase()):'/';$('#rider-content').innerHTML=`<section class="rider-hero"><div class="rider-number">${esc(first.bib||'—')}</div><div><div class="eyebrow">${esc(first.tournament||'Rider')}</div><h1>${esc(rider.name)}</h1><p>Bib ${esc(first.bib||'—')} · ${esc(first.tournament||'OWAR 2026')}</p></div></section><section class="rider-stats"><div><span>Recorded races</span><strong>${records.length}</strong></div><div><span>Fastest time</span><strong>${esc(fastest?.time||'—')}</strong></div></section><section class="race-table history-card"><div class="history-heading"><span>Current event</span><h2>Every recorded time</h2></div><div class="table-scroll"><table class="rider-times"><colgroup><col class="rider-time-stage"><col class="rider-time-race"><col class="rider-time-position"><col class="rider-time-value"></colgroup><thead><tr><th>Stage</th><th>Race</th><th>Position</th><th>Time</th></tr></thead><tbody>${records.map(x=>`<tr><td><span class="history-stage">${esc(x.stage||x.level||'Results')}</span></td><td>${esc(x.race)}</td><td>${esc(x.position)}</td><td class="time">${esc(x.time)}</td></tr>`).join('')||'<tr><td colspan="4">No recorded times yet.</td></tr>'}</tbody></table></div></section>${historical.length?historic(historical):historySearch()}`;wireHistorySearch(id)}catch{$('#rider-content').innerHTML='<p class="empty">This rider record is not available yet.</p>'}}
render();
